import{_ as a,c as s,o as n,a1 as r}from"./chunks/framework.C3Hmo1as.js";const c=JSON.parse('{"title":"证券基础知识","description":null,"frontmatter":{"title":"证券基础知识","description":null,"date":"2026-02-18T00:00:00.000Z","tags":["PSIF"],"outline":[2,3]},"headers":[],"relativePath":"trader/securities-basics.md","filePath":"trader/securities-basics.md"}'),o={name:"trader/securities-basics.md"};function d(l,t,e,p,i,h){return n(),s("div",null,[...t[0]||(t[0]=[r(`<h2 id="有价证券" tabindex="-1">有价证券 <a class="header-anchor" href="#有价证券" aria-label="Permalink to &quot;有价证券&quot;">​</a></h2><h3 id="有价证券的定义" tabindex="-1">有价证券的定义 <a class="header-anchor" href="#有价证券的定义" aria-label="Permalink to &quot;有价证券的定义&quot;">​</a></h3><p><strong>有价证券</strong>是指标有票面金额，用于证明持有人或该证券指定的特定主体对特定财产拥有<code>所有权</code>或<code>债权</code>的凭证。 它属于<strong>虚拟资本</strong>的一种形式——本身没有实际价值，但具有市场价格，其价格取决于所代表的财产权利的预期收益。</p><p>简单来说，有价证券是将财产权利&quot;证券化&quot;的载体，持有人可通过它获得收益（如股息、利息）或行使权利（如投票权、提货权）。</p><hr><h3 id="有价证券的主要分类" tabindex="-1">有价证券的主要分类 <a class="header-anchor" href="#有价证券的主要分类" aria-label="Permalink to &quot;有价证券的主要分类&quot;">​</a></h3><p>有价证券可从多个维度进行分类，以下是常见分类方式：</p><h4 id="一、按财产权利性质-基础分类" tabindex="-1">一、按财产权利性质（基础分类） <a class="header-anchor" href="#一、按财产权利性质-基础分类" aria-label="Permalink to &quot;一、按财产权利性质（基础分类）&quot;">​</a></h4><p>这是最根本的分类方式，分为三类：</p><ol><li><strong>商品证券</strong>：证明持有人对特定商品拥有所有权，如提货单、运货单、仓单等。</li><li><strong>货币证券</strong>：证明持有人对货币拥有索取权，如支票、汇票、本票等。</li><li><strong>资本证券</strong>：证明持有人对资本拥有所有权或债权，如<strong>股票、债券、基金</strong>等。<br> → <strong>狭义的&quot;有价证券&quot;通常特指资本证券</strong>，也是日常投资中最常见的类型。</li></ol><h4 id="二、按发行主体" tabindex="-1">二、按发行主体 <a class="header-anchor" href="#二、按发行主体" aria-label="Permalink to &quot;二、按发行主体&quot;">​</a></h4><ul><li><strong>政府证券</strong>：由中央政府发行（如国债）。</li><li><strong>政府机构证券</strong>：由政府支持的机构发行（如政策性金融债）。</li><li><strong>金融证券</strong>：由银行、证券公司等金融机构发行（如金融债、次级债）。</li><li><strong>公司证券</strong>：由企业发行（如公司债、企业股票）。</li></ul><h4 id="三、按交易场所" tabindex="-1">三、按交易场所 <a class="header-anchor" href="#三、按交易场所" aria-label="Permalink to &quot;三、按交易场所&quot;">​</a></h4><ul><li><strong>上市证券</strong>：在证券交易所挂牌交易（如沪深交易所的股票、债券）。</li><li><strong>非上市证券</strong>：不在交易所公开交易，通过场外市场转让（如私募债、非上市股权）。</li></ul><h4 id="四、按募集方式" tabindex="-1">四、按募集方式 <a class="header-anchor" href="#四、按募集方式" aria-label="Permalink to &quot;四、按募集方式&quot;">​</a></h4><ul><li><strong>公募证券</strong>：向不特定公众公开发行，监管严格，流动性高。</li><li><strong>私募证券</strong>：向特定合格投资者非公开发行，门槛较高，流动性较低。</li></ul><h4 id="五、按记名方式" tabindex="-1">五、按记名方式 <a class="header-anchor" href="#五、按记名方式" aria-label="Permalink to &quot;五、按记名方式&quot;">​</a></h4><ul><li><strong>记名证券</strong>：记载持有人姓名，转让需办理过户手续（安全性高）。</li><li><strong>不记名证券</strong>：不记载持有人姓名，交付即转让（流动性强但风险较高）。</li></ul><hr><h3 id="常见有价证券示例" tabindex="-1">常见有价证券示例 <a class="header-anchor" href="#常见有价证券示例" aria-label="Permalink to &quot;常见有价证券示例&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>代表品种</th></tr></thead><tbody><tr><td><strong>股票</strong></td><td>A股、B股、H股、优先股等</td></tr><tr><td><strong>债券</strong></td><td>国债、企业债、可转债、金融债</td></tr><tr><td><strong>基金</strong></td><td>股票基金、债券基金、ETF等</td></tr><tr><td><strong>衍生品</strong></td><td>权证、期权（部分国家纳入）</td></tr></tbody></table><h2 id="电商代金券、月饼券、蟹券" tabindex="-1">电商代金券、月饼券、蟹券 <a class="header-anchor" href="#电商代金券、月饼券、蟹券" aria-label="Permalink to &quot;电商代金券、月饼券、蟹券&quot;">​</a></h2><blockquote><p><strong>电商代金券、月饼券、蟹券均不属于法律意义上的“有价证券”</strong>（特别是《证券法》规范的证券），但它们在实践中存在一些值得探讨的灰色现象。</p></blockquote><hr><h3 id="法律定性-不属于有价证券" tabindex="-1">法律定性：不属于有价证券 <a class="header-anchor" href="#法律定性-不属于有价证券" aria-label="Permalink to &quot;法律定性：不属于有价证券&quot;">​</a></h3><h4 id="_1-监管依据不同" tabindex="-1">1. <strong>监管依据不同</strong> <a class="header-anchor" href="#_1-监管依据不同" aria-label="Permalink to &quot;1. **监管依据不同**&quot;">​</a></h4><ul><li>中国《证券法》采取<strong>列举式定义</strong>，明确规范的“证券”主要包括：股票、公司债券、存托凭证、证券投资基金份额等<strong>资本证券</strong>。代金券、月饼券等不在其列。</li><li>这类券实际属于<strong>单用途商业预付卡</strong>或商品提货凭证，受商务部《单用途商业预付卡管理办法（试行）》监管，而非《证券法》。</li></ul><h4 id="_2-权利性质不同" tabindex="-1">2. <strong>权利性质不同</strong> <a class="header-anchor" href="#_2-权利性质不同" aria-label="Permalink to &quot;2. **权利性质不同**&quot;">​</a></h4><table tabindex="0"><thead><tr><th>特征</th><th>有价证券（资本证券）</th><th>代金券/月饼券/蟹券</th></tr></thead><tbody><tr><td><strong>权利本质</strong></td><td>代表投资性财产权（股权/债权），具有融资功能</td><td>代表对特定商品/服务的<strong>预付消费索取权</strong></td></tr><tr><td><strong>流通目的</strong></td><td>投资、融资、资产配置</td><td>消费、礼品馈赠</td></tr><tr><td><strong>法律属性</strong></td><td>受《证券法》严格监管，需信息披露</td><td>受商务部门监管，侧重消费者权益保护</td></tr><tr><td><strong>典型例子</strong></td><td>股票、国债、企业债</td><td>电商满减券、超市提货单、月饼礼券</td></tr></tbody></table><blockquote><p>💡 <strong>关键区别</strong>：有价证券的核心是<strong>投资属性</strong>（预期获得资本增值或固定收益），而代金券等本质是<strong>预付消费工具</strong>，不具备融资功能。</p></blockquote><hr><h3 id="实践中的灰色现象" tabindex="-1">实践中的灰色现象 <a class="header-anchor" href="#实践中的灰色现象" aria-label="Permalink to &quot;实践中的灰色现象&quot;">​</a></h3><p>尽管法律上不属于证券，但月饼券、蟹券在现实中形成了<strong>非正规的二级市场流转</strong>，产生类似金融衍生品的操作：</p><ul><li><strong>“炒券”链条</strong>：商家以400元售出面值500元的蟹券 → 消费者以250元卖给“黄牛” → 黄牛以300元回售给商家，全程无需实物交割。</li><li><strong>空转套利</strong>：月饼尚未生产，仅凭一张券在经销商、消费者、回收商之间流转，即可产生GDP和利润。</li><li><strong>期货化特征</strong>：蟹券将保质期短的大闸蟹“证券化”，实现跨期交易，类似商品期货。</li></ul><p>⚠️ 但需注意：这种民间自发流转<strong>不改变其法律性质</strong>，仍属于预付卡范畴，不受证券监管。若涉及大规模非法集资或诈骗，可能触犯《刑法》而非《证券法》。</p><h2 id="上交所、深交所、北交所" tabindex="-1">上交所、深交所、北交所 <a class="header-anchor" href="#上交所、深交所、北交所" aria-label="Permalink to &quot;上交所、深交所、北交所&quot;">​</a></h2><ul><li>这是三家<code>全国性证券交易所</code>，地位平等，各自负责不同类型股票的交易。</li></ul><table tabindex="0"><thead><tr><th>交易所</th><th>成立时间</th><th>所在地</th><th>组织形式</th><th>运营主体</th></tr></thead><tbody><tr><td><strong>上交所</strong></td><td>1990年</td><td>上海</td><td>会员制</td><td>上海证券交易所</td></tr><tr><td><strong>深交所</strong></td><td>1990年</td><td>深圳</td><td>会员制</td><td>深圳证券交易所</td></tr><tr><td><strong>北交所</strong></td><td>2021年11月</td><td><strong>北京</strong></td><td><strong>公司制</strong></td><td>全国股转公司全资子公司</td></tr></tbody></table><ul><li><p><strong>关键结论</strong></p><ul><li>三者<strong>交易系统完全独立</strong>，股票代码、交易规则、上市标准均不同</li><li>通过<strong>中国证券登记结算公司（中国结算）</strong> 统一进行登记、清算、交收</li><li>投资者用<strong>同一个A股账户</strong>即可交易三地股票（需分别开通权限）</li></ul></li><li><p>三大交易所核心差异</p></li></ul><table tabindex="0"><thead><tr><th>维度</th><th>上交所/深交所</th><th>北交所</th></tr></thead><tbody><tr><td><strong>组织形式</strong></td><td>会员制（非营利）</td><td>公司制（中国首次试点）</td></tr><tr><td><strong>服务对象</strong></td><td>成熟大型企业/硬科技企业</td><td>专精特新&quot;小巨人&quot;等创新型中小企业</td></tr><tr><td><strong>上市路径</strong></td><td>直接IPO</td><td>需先在新三板挂牌满12个月</td></tr><tr><td><strong>转板机制</strong></td><td>无</td><td>可转板至科创板/创业板（需符合标准）</td></tr></tbody></table><blockquote><p>💡 <strong>通俗理解</strong>：三所如同&quot;三所平行大学&quot;——上交所像985（央企/大盘蓝筹）、深交所像211（知名民企/成长企业）、北交所像&quot;特色应用型大学&quot;（专精特新中小企业），三者独立招生、独立教学，但学生（企业）可申请转学（转板）。</p></blockquote><h2 id="中国资本市场的多层次体系" tabindex="-1">中国资本市场的多层次体系 <a class="header-anchor" href="#中国资本市场的多层次体系" aria-label="Permalink to &quot;中国资本市场的多层次体系&quot;">​</a></h2><blockquote><p>中国资本市场已形成&quot;<strong>金字塔型</strong>&quot;多层次体系，各板块<strong>错位发展、功能互补</strong>，服务不同发展阶段的企业。</p></blockquote><h3 id="一图看懂各板块定位" tabindex="-1">一图看懂各板块定位 <a class="header-anchor" href="#一图看懂各板块定位" aria-label="Permalink to &quot;一图看懂各板块定位&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>🔺 塔尖：沪深主板（成熟期大型企业）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ 科创板（硬科技创新企业）</span></span>
<span class="line"><span>├─ 创业板（成长型创新创业企业）</span></span>
<span class="line"><span>├─ 北交所（专精特新中小企业）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ 新三板·创新层（优质中小微企业）</span></span>
<span class="line"><span>├─ 新三板·基础层（初创期中小微企业）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>🔻 塔基：区域性股权市场（四板/新四板）（地方小微企业孵化）</span></span></code></pre></div><hr><h3 id="各板块详细对比" tabindex="-1">各板块详细对比 <a class="header-anchor" href="#各板块详细对比" aria-label="Permalink to &quot;各板块详细对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>板块</th><th>定位</th><th>服务对象</th><th>投资者门槛</th><th>交易机制</th><th>核心特点</th></tr></thead><tbody><tr><td><strong>主板</strong><br>（上交所/深交所）</td><td>大盘蓝筹主阵地</td><td>业务成熟、业绩稳定、规模较大的行业龙头</td><td>无特殊门槛<br>（普通股票账户即可）</td><td>涨跌幅±10%<br>（ST股±5%）</td><td>✅ 盈利要求最严<br>✅ 强调&quot;大盘蓝筹&quot;属性<br>✅ 最近3年净利润累计≥1.5亿元</td></tr><tr><td><strong>科创板</strong><br>（上交所）</td><td>硬科技创新平台</td><td>面向世界科技前沿、国家重大需求的科技企业</td><td>50万资产+2年经验</td><td>涨跌幅±20%<br>上市前5日无限制</td><td>✅ 允许未盈利企业上市<br>✅ 5套差异化上市标准<br>✅ 研发投入、技术优势是核心</td></tr><tr><td><strong>创业板</strong><br>（深交所）</td><td>成长型创新创业</td><td>&quot;三创四新&quot;企业（创新、创造、创意；新技术、新产业、新业态、新模式）</td><td>10万资产+2年经验</td><td>涨跌幅±20%<br>上市前5日无限制</td><td>✅ 兼顾成长性与创新性<br>✅ 3套上市标准，门槛低于主板</td></tr><tr><td><strong>北交所</strong></td><td>专精特新主阵地</td><td>创新型中小企业，尤其是&quot;专精特新&quot;企业</td><td>50万资产+2年经验</td><td>涨跌幅±30%<br>上市首日无限制</td><td>✅ 由新三板精选层升级而来<br>✅ 企业需先在新三板创新层挂牌满12个月</td></tr><tr><td><strong>新三板</strong><br>（全国股转系统）</td><td>中小微企业培育平台</td><td>尚未达到上市标准的中小微企业</td><td>基础层：200万<br>创新层：100万</td><td>集合竞价/做市交易<br>涨跌幅限制较灵活</td><td>✅ 分基础层、创新层<br>✅ 是企业进入更高层次市场的&quot;孵化器&quot;</td></tr><tr><td><strong>四板</strong><br>（区域性股权市场）</td><td>地方小微企业服务基地</td><td>省级行政区域内的小微企业、初创企业</td><td>合格投资者<br>（门槛由地方规定）</td><td>协议转让/定向发行<br>非公开、低频交易</td><td>✅ 地方政府管理，非公开发行<br>✅ 融资+规范+政策对接综合平台<br>✅ 成本最低、门槛最低</td></tr></tbody></table><hr><h3 id="上市-挂牌条件差异-财务维度简化版" tabindex="-1">上市/挂牌条件差异（财务维度简化版） <a class="header-anchor" href="#上市-挂牌条件差异-财务维度简化版" aria-label="Permalink to &quot;上市/挂牌条件差异（财务维度简化版）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>板块</th><th>盈利要求</th><th>营收/市值要求</th><th>持续经营时间</th></tr></thead><tbody><tr><td>主板</td><td>最近3年净利润累计≥1.5亿</td><td>市值/营收组合标准</td><td>≥3年</td></tr><tr><td>科创板</td><td>可未盈利（5套标准可选）</td><td>市值10-40亿+研发/营收指标</td><td>≥2年</td></tr><tr><td>创业板</td><td>最近2年净利润累计≥5000万</td><td>市值10-50亿+营收指标</td><td>≥2年</td></tr><tr><td>北交所</td><td>最近1-2年净利润≥1500-2500万</td><td>市值2-15亿+成长/研发指标</td><td>创新层挂牌满12个月</td></tr><tr><td>新三板</td><td>基础层：净利润≥600万或营收≥3000万</td><td>无硬性市值要求</td><td>≥2年（新经济领域可1年）</td></tr><tr><td>四板</td><td>无统一财务指标</td><td>由地方股权中心制定</td><td>通常≥1年</td></tr></tbody></table><blockquote><p>数据来源：证监会及交易所2023-2024年注册制规则</p></blockquote><h3 id="投资者适当性管理-个人开户门槛" tabindex="-1">投资者适当性管理（个人开户门槛） <a class="header-anchor" href="#投资者适当性管理-个人开户门槛" aria-label="Permalink to &quot;投资者适当性管理（个人开户门槛）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>🔒 风险匹配原则：板块风险越高 → 投资者门槛越高</span></span>
<span class="line"><span></span></span>
<span class="line"><span>主板：✅ 无资产门槛（普通账户）</span></span>
<span class="line"><span>创业板：💰 10万元 + 2年交易经验</span></span>
<span class="line"><span>科创板/北交所：💰💰 50万元 + 2年交易经验  </span></span>
<span class="line"><span>新三板创新层：💰💰💰 100万元</span></span>
<span class="line"><span>新三板基础层：💰💰💰💰 200万元</span></span>
<span class="line"><span>四板：由地方规定，通常要求合格投资者认定</span></span></code></pre></div><h3 id="转板机制-企业上升通道" tabindex="-1">转板机制（企业上升通道） <a class="header-anchor" href="#转板机制-企业上升通道" aria-label="Permalink to &quot;转板机制（企业上升通道）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>四板 → 新三板基础层 → 创新层 → 北交所 → 科创板/创业板</span></span>
<span class="line"><span>                              ↘ 主板（符合条件可直接申请）</span></span></code></pre></div><blockquote><p>北交所上市公司满足条件可申请转板至科创板或创业板，实现&quot;层层递进&quot;</p></blockquote><hr><h3 id="❓-常见疑问解答" tabindex="-1">❓ 常见疑问解答 <a class="header-anchor" href="#❓-常见疑问解答" aria-label="Permalink to &quot;❓ 常见疑问解答&quot;">​</a></h3><p><strong>Q：四板和新三板有什么区别？</strong><br> A：四板是<strong>区域性私募市场</strong>，由地方政府管理，服务本地小微企业；新三板是<strong>全国性公开市场</strong>，由证监会监管，企业可面向全国投资者融资。四板挂牌成本更低、门槛更低，更适合初创期企业。</p><p><strong>Q：个人投资者能参与四板吗？</strong><br> A：四板属于私募市场，仅向<strong>合格投资者</strong>开放（通常要求金融资产≥50万元+投资经验），且投资标的流动性较低，普通散户参与难度大、风险高。</p><p><strong>Q：各板块风险如何排序？</strong><br> A：从风险角度（由高到低）：<br> 四板 ＞ 新三板基础层 ＞ 新三板创新层 ＞ 北交所 ＞ 创业板 ≈ 科创板 ＞ 主板<br><em>风险与收益并存，投资者应根据自身风险承受能力选择</em></p><h2 id="集合竞价与连续竞价" tabindex="-1">集合竞价与连续竞价 <a class="header-anchor" href="#集合竞价与连续竞价" aria-label="Permalink to &quot;集合竞价与连续竞价&quot;">​</a></h2><p>在国内证券市场（以上交所、深交所A股为主流参考，含主板、科创板、创业板、北交所等），集合竞价与连续竞价的时间段及本质如下：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  🇨🇳 中国A股交易时段简图（沪深交易所）            │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  📅 交易日：周一至周五（法定节假日除外）          │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                                                 │</span></span>
<span class="line"><span>│  🟡 集合竞价阶段                                  │</span></span>
<span class="line"><span>│  ┌─────────────────┐                            │</span></span>
<span class="line"><span>│  │ 09:15 ── 09:20 │ ✅ 可申报 + 可撤单          │</span></span>
<span class="line"><span>│  ├─────────────────┤                            │</span></span>
<span class="line"><span>│  │ 09:20 ── 09:25 │ ✅ 可申报 + ❌ 不可撤单     │</span></span>
<span class="line"><span>│  └─────────────────┘                            │</span></span>
<span class="line"><span>│           ↓                                     │</span></span>
<span class="line"><span>│  🔵 连续竞价（早盘）                              │</span></span>
<span class="line"><span>│  ┌─────────────────┐                            │</span></span>
<span class="line"><span>│  │ 09:30 ── 11:30 │ ✅ 正常交易时段             │</span></span>
<span class="line"><span>│  └─────────────────┘                            │</span></span>
<span class="line"><span>│           ↓                                     │</span></span>
<span class="line"><span>│  ⚪ 午间休市                                     │</span></span>
<span class="line"><span>│  ┌─────────────────┐                            │</span></span>
<span class="line"><span>│  │ 11:30 ── 13:00 │ 🍱 休息/不接受订单          │</span></span>
<span class="line"><span>│  └─────────────────┘                            │</span></span>
<span class="line"><span>│           ↓                                     │</span></span>
<span class="line"><span>│  🔵 连续竞价（午盘）                              │</span></span>
<span class="line"><span>│  ┌─────────────────┐                            │</span></span>
<span class="line"><span>│  │ 13:00 ── 14:57 │ ✅ 正常交易时段             │</span></span>
<span class="line"><span>│  └─────────────────┘                            │</span></span>
<span class="line"><span>│           ↓                                     │</span></span>
<span class="line"><span>│  🟢 收盘集合竞价（仅深市）                        │</span></span>
<span class="line"><span>│  ┌─────────────────┐                            │</span></span>
<span class="line"><span>│  │ 14:57 ── 15:00 │ ✅ 可申报 + ❌ 不可撤单     │</span></span>
<span class="line"><span>│  └─────────────────┘                            │</span></span>
<span class="line"><span>│                                                 │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  📊 关键数据：                                   │</span></span>
<span class="line"><span>│  • 全天交易时长：4小时（不含午休）               │</span></span>
<span class="line"><span>│  • 开盘价产生：09:25（集合竞价撮合）            │</span></span>
<span class="line"><span>│  • 收盘价产生：15:00（沪市连续竞价/深市集合竞价）│</span></span>
<span class="line"><span>│  • 北向资金订单接受：09:10起（港交所系统）      │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h3 id="具体时间段-以现行规则为准" tabindex="-1">具体时间段（以现行规则为准） <a class="header-anchor" href="#具体时间段-以现行规则为准" aria-label="Permalink to &quot;具体时间段（以现行规则为准）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>竞价类型</th><th>时间段</th><th>关键细节</th></tr></thead><tbody><tr><td><strong>集合竞价</strong></td><td><strong>开盘</strong>：9:15–9:25<br><strong>收盘</strong>：14:57–15:00</td><td>• 9:15–9:20：可申报、可撤单（易被虚假申报利用，需警惕）<br>• 9:20–9:25 &amp; 14:57–15:00：可申报、<strong>不可撤单</strong>（防尾盘/开盘操纵）<br>• 9:25产生开盘价；15:00产生收盘价</td></tr><tr><td><strong>连续竞价</strong></td><td>9:30–11:30，<br>13:00–14:57</td><td>• 9:25–9:30为系统静默期（不接受当日新申报，仅处理隔夜委托）<br>• 科创板/创业板另有盘后固定价格交易（15:05–15:30），但属独立机制，不计入连续竞价</td></tr></tbody></table><blockquote><p>注：北交所规则基本一致；港股、期货等市场规则不同，此处不展开。</p></blockquote><hr><h3 id="本质解析-核心区别与设计逻辑" tabindex="-1">本质解析（核心区别与设计逻辑） <a class="header-anchor" href="#本质解析-核心区别与设计逻辑" aria-label="Permalink to &quot;本质解析（核心区别与设计逻辑）&quot;">​</a></h3><h4 id="🔹-集合竞价-定期拍卖式价格发现" tabindex="-1">🔹 集合竞价：<strong>“定期拍卖式价格发现”</strong> <a class="header-anchor" href="#🔹-集合竞价-定期拍卖式价格发现" aria-label="Permalink to &quot;🔹 集合竞价：**“定期拍卖式价格发现”**&quot;">​</a></h4><ul><li><strong>机制内核</strong>：在固定窗口集中接收全部有效委托，按 <strong>“最大成交量原则”</strong>（辅以前收盘价贴近度、最小剩余量等细则）一次性计算唯一成交价，所有匹配订单按此价统一成交。</li><li><strong>核心目的</strong>： <ul><li><strong>开盘</strong>：消化隔夜信息（如外围市场、公告），避免连续竞价初期因信息不对称导致价格剧烈跳空；</li><li><strong>收盘</strong>：形成权威收盘价（用于基金净值、指数计算等），抑制尾盘操纵。</li></ul></li><li><strong>理论本质</strong>：属于 <strong>“定期呼叫拍卖”（Periodic Call Auction）</strong>，牺牲瞬时流动性换取关键时点的价格公允性与市场稳定性。不可撤单阶段的设计直接针对历史操纵行为（如“涨停板敢死队”虚假申报）。</li></ul><h4 id="🔹-连续竞价-动态流动性供给" tabindex="-1">🔹 连续竞价：<strong>“动态流动性供给”</strong> <a class="header-anchor" href="#🔹-连续竞价-动态流动性供给" aria-label="Permalink to &quot;🔹 连续竞价：**“动态流动性供给”**&quot;">​</a></h4><ul><li><strong>机制内核</strong>：订单按 <strong>“价格优先→时间优先”</strong> 实时撮合（买一≥卖一时即时成交），价格连续变动，未成交订单进入订单簿等待。</li><li><strong>核心目的</strong>：提供全天候交易流动性，使价格能灵敏反映新信息（如突发新闻、大单冲击），满足投资者即时交易需求。</li><li><strong>理论本质</strong>：属于 <strong>“连续双拍卖”（Continuous Double Auction）</strong>，强调市场效率与价格连续性，是日常交易的主干。但易受短期噪声交易、高频策略影响，产生瞬时波动。</li></ul><hr><h3 id="为何如此设计-——制度逻辑升华" tabindex="-1">为何如此设计？——制度逻辑升华 <a class="header-anchor" href="#为何如此设计-——制度逻辑升华" aria-label="Permalink to &quot;为何如此设计？——制度逻辑升华&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>集合竞价</th><th>连续竞价</th></tr></thead><tbody><tr><td><strong>核心价值</strong></td><td>公平性、价格基准权威性</td><td>流动性、交易效率</td></tr><tr><td><strong>适用场景</strong></td><td>信息集中释放时点（开/收盘）</td><td>信息持续流动的交易时段</td></tr><tr><td><strong>市场角色</strong></td><td>“锚定价格”（减少开盘跳空、稳定收盘）</td><td>“传递价格”（实时反映供需）</td></tr><tr><td><strong>制度演进</strong></td><td>收盘集合竞价2018年全面推行（防“秒拉秒砸”）；9:20后禁撤单强化公平</td><td>涨跌幅限制、有效申报范围等配套规则抑制连续竞价风险</td></tr></tbody></table><blockquote><p>💡 <strong>关键洞见</strong>：二者并非孤立存在，而是互补共生——<br> 集合竞价为连续竞价提供<strong>理性起点与终点</strong>（如开盘价避免9:30瞬间巨震），连续竞价为集合竞价积累<strong>订单深度与市场预期</strong>（如尾盘订单影响收盘价）。这种“定期拍卖+连续交易”混合机制，是全球成熟市场（如NYSE、Euronext）的通用设计，平衡了<strong>价格发现效率</strong>与<strong>交易流动性</strong>这对核心矛盾，同时嵌入中国特色的防操纵细节（如不可撤单时段），体现监管对公平与稳定的双重追求。</p></blockquote>`,79)])])}const b=a(o,[["render",d]]);export{c as __pageData,b as default};
